<section class="single-herbs-guide__section" aria-labelledby="topic-twentysix-yang"><h4 id="topic-twentysix-yang"><?php echo s($yintonifytext('Yang comparative fingerprints', 'Huellas comparativas de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($yintonifytext('Relative study indices—not doses or efficacy percentages. Values were read directly from Yang figures 14.9–14.14; only exact current-list entries are graphed.', 'Índices relativos de estudio—no dosis ni porcentajes. Valores leídos directamente de figuras 14.9–14.14 de Yang; solo se grafican entradas exactas de la lista actual.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach ($yintonifycharts as $chart): ?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart[0]); ?></h5><small><?php echo s($chart[1]); ?></small><?php foreach ($chart[2] as $name => $value): ?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name); ?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int)$value; ?>%"></span></span><b><?php echo (int)$value; ?></b></div><?php endforeach; ?></article><?php endforeach; ?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($yintonifytext('Fast reading:', 'Lectura rápida:')); ?></strong> <?php echo s($yintonifytext('Tian Men Dong wins when Lung dryness extends to Kidney Heat; Shi Hu wins in severe Stomach dryness; Mai Men Dong wins when Heart irritability joins Lung–Stomach dryness.', 'Tian Men Dong gana cuando sequedad de Pulmón alcanza Calor de Riñón; Shi Hu en sequedad grave de Estómago; Mai Men Dong cuando irritabilidad de Corazón se suma a Pulmón–Estómago.')); ?></p></section>

